import { useEffect, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { getProducts } from '../services/api';
import ProductCard from '../components/product/ProductCard';
import './ProductsPage.css';

export default function ProductsPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const [products, setProducts] = useState([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [priceRange, setPriceRange] = useState([0, 20000]);
  const [selectedSizes, setSelectedSizes] = useState([]);
  const [showFilters, setShowFilters] = useState(false);

  const category = searchParams.get('category') || '';
  const sort = searchParams.get('sort') || '';
  const search = searchParams.get('search') || '';

  useEffect(() => {
    setLoading(true);
    const params = { limit: 12 };
    if (category) params.category = category;
    if (sort) params.sort = sort;
    if (search) params.search = search;

    getProducts(params)
      .then(({ data }) => {
        let filtered = data.products;

        // Filter by price range
        filtered = filtered.filter(
          (p) => p.price >= priceRange[0] && p.price <= priceRange[1]
        );

        // Filter by sizes
        if (selectedSizes.length > 0) {
          filtered = filtered.filter((p) =>
            p.sizes?.some((s) => selectedSizes.includes(s))
          );
        }

        setProducts(filtered);
        setTotal(filtered.length);
      })
      .catch((err) => console.error(err))
      .finally(() => setLoading(false));
  }, [category, sort, search, priceRange, selectedSizes]);

  const set = (key, val) => {
    const p = new URLSearchParams(searchParams);
    if (val) p.set(key, val);
    else p.delete(key);
    setSearchParams(p);
  };

  const toggleSize = (size) => {
    setSelectedSizes((prev) =>
      prev.includes(size) ? prev.filter((s) => s !== size) : [...prev, size]
    );
  };

  const clearFilters = () => {
    setPriceRange([0, 20000]);
    setSelectedSizes([]);
    setSearchParams({});
  };

  const hasFilters = category || sort || search || selectedSizes.length > 0 || priceRange[0] > 0 || priceRange[1] < 20000;

  const SIZES = ['XS', 'S', 'M', 'L', 'XL', 'XXL', '28', '30', '32', '34', '36'];

  return (
    <div className="products-page">
      <div className="products-header">
        <h1 className="products-title">
          {category ? category.charAt(0).toUpperCase() + category.slice(1) : 'All Products'}
          <span className="products-count"> ({total})</span>
        </h1>
        <div className="products-controls">
          <input
            className="form-input search-input"
            placeholder="🔍 Search products..."
            value={search}
            onChange={(e) => set('search', e.target.value)}
          />
          <select className="form-select" value={sort} onChange={(e) => set('sort', e.target.value)}>
            <option value="">Sort: Featured</option>
            <option value="newest">Newest First</option>
            <option value="price_asc">Price: Low to High</option>
            <option value="price_desc">Price: High to Low</option>
          </select>
          <button
            className={`btn btn-outline btn-sm filter-toggle ${showFilters ? 'active' : ''}`}
            onClick={() => setShowFilters(!showFilters)}
          >
            🔧 Filters {hasFilters && <span className="filter-dot" />}
          </button>
          {hasFilters && (
            <button className="btn btn-outline btn-sm" onClick={clearFilters}>
              ✕ Clear
            </button>
          )}
        </div>
      </div>

      <div className="products-layout">
        {/* Sidebar */}
        <aside className={`products-sidebar ${showFilters ? 'open' : ''}`}>

          {/* Category */}
          <div className="filter-section">
            <h3>Category</h3>
            {[
              { label: 'All', value: '' },
              { label: 'Women', value: 'women' },
              { label: 'Men', value: 'men' },
              { label: 'Accessories', value: 'accessories' },
            ].map((c) => (
              <button
                key={c.value}
                className={`filter-item ${category === c.value ? 'active' : ''}`}
                onClick={() => set('category', c.value)}
              >
                {c.label}
              </button>
            ))}
          </div>

          {/* Price Range */}
          <div className="filter-section">
            <h3>Price Range</h3>
            <div className="price-range-labels">
              <span>₹{priceRange[0].toLocaleString()}</span>
              <span>₹{priceRange[1].toLocaleString()}</span>
            </div>
            <input
              type="range" min="0" max="20000" step="500"
              value={priceRange[1]}
              onChange={(e) => setPriceRange([priceRange[0], Number(e.target.value)])}
              className="price-slider"
            />
            <div className="price-presets">
              {[
                { label: 'Under ₹2k', min: 0, max: 2000 },
                { label: '₹2k–5k', min: 2000, max: 5000 },
                { label: '₹5k–10k', min: 5000, max: 10000 },
                { label: 'Above ₹10k', min: 10000, max: 20000 },
              ].map((p) => (
                <button
                  key={p.label}
                  className={`price-preset ${priceRange[0] === p.min && priceRange[1] === p.max ? 'active' : ''}`}
                  onClick={() => setPriceRange([p.min, p.max])}
                >
                  {p.label}
                </button>
              ))}
            </div>
          </div>

          {/* Sizes */}
          <div className="filter-section">
            <h3>Size</h3>
            <div className="size-filter-grid">
              {SIZES.map((size) => (
                <button
                  key={size}
                  className={`size-filter-btn ${selectedSizes.includes(size) ? 'active' : ''}`}
                  onClick={() => toggleSize(size)}
                >
                  {size}
                </button>
              ))}
            </div>
          </div>

          {/* New Arrivals */}
          <div className="filter-section">
            <h3>Availability</h3>
            <button
              className={`filter-item ${sort === 'newest' ? 'active' : ''}`}
              onClick={() => set('sort', sort === 'newest' ? '' : 'newest')}
            >
              New Arrivals
            </button>
          </div>

          {hasFilters && (
            <button className="btn btn-outline btn-sm" style={{ width: '100%', justifyContent: 'center', marginTop: '1rem' }} onClick={clearFilters}>
              ✕ Clear All Filters
            </button>
          )}
        </aside>

        {/* Grid */}
        <div>
          {/* Active Filters */}
          {hasFilters && (
            <div className="active-filters">
              {category && <span className="filter-tag">{category} ✕</span>}
              {search && <span className="filter-tag">"{search}" ✕</span>}
              {selectedSizes.map((s) => (
                <span key={s} className="filter-tag" onClick={() => toggleSize(s)}>{s} ✕</span>
              ))}
              {(priceRange[0] > 0 || priceRange[1] < 20000) && (
                <span className="filter-tag">₹{priceRange[0].toLocaleString()} – ₹{priceRange[1].toLocaleString()} ✕</span>
              )}
            </div>
          )}

          <div className="products-grid">
            {loading ? (
              <div className="page-loader"><div className="spinner" /></div>
            ) : products.length === 0 ? (
              <div className="no-products">
                <div style={{ fontSize: 48 }}>🔍</div>
                <h3>No products found</h3>
                <p>Try adjusting your filters or search term</p>
                <button className="btn btn-accent mt-2" onClick={clearFilters}>Clear Filters</button>
              </div>
            ) : (
              products.map((p) => <ProductCard key={p._id} product={p} />)
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
